// DEV-002: UniFFI [WireSigner] adapter that routes signing through
// the `FrameSigner` callback interface. The Ed25519 private key
// NEVER appears as bytes in the JVM — the Rust side calls back into
// a [com.sy.deunlock.android.approve.KeystoreFrameSigner] (production)
// or a test fake (unit tests) which executes the sign operation under
// Android Keystore with `setUserAuthenticationRequired(true)` per
// SPEC §3.2 D6.
//
// The class itself contains no JNI — the binding is auto-generated by
// `uniffi-bindgen` and lives under
// `crates/deunlock-mobile/bindings/kotlin/uniffi/deunlock_mobile/`. The
// grep guard in `make android-test` asserts no hand-written `external
// fun` exists in this file or any other under `deunlock-android/`.
package com.sy.deunlock.android.approve

import uniffi.deunlock_mobile.FrameSigner

/**
 * Production [WireSigner] backed by the UniFFI Kotlin binding.
 *
 * Wraps a [FrameSigner] — the production signer is a
 * [KeystoreFrameSigner] minted with the bond's Keystore alias; the
 * test wiring injects a fake that returns a canned signature without
 * touching the Keystore.
 */
public class UniffiWireSigner(
    private val frameSigner: FrameSigner,
    private val bondKey: ByteArray = ByteArray(0),
) : WireSigner {
    override suspend fun signWire(bondKey: ByteArray, frameBytes: ByteArray): WireSignResult {
        return try {
            // `buildResponseSignature` verifies the challenge MAC under the bond
            // key, signs the canonical payload (v1 frame body or v2 transcript)
            // and returns the raw 64-byte signature the daemon reads back.
            // Signing is unreachable for a frame whose MAC does not verify
            // (AUDIT-001 D-02).
            val signature = uniffi.deunlock_mobile.buildResponseSignature(bondKey, frameSigner, frameBytes)
            WireSignResult.Ok(signature)
        } catch (t: Throwable) {
            WireSignResult.Failure(t.message ?: t::class.java.simpleName)
        }
    }

    override fun describeChallenge(frameBytes: ByteArray): String {
        if (bondKey.isEmpty()) {
            return ""
        }
        return try {
            val info = uniffi.deunlock_mobile.parseChallenge(bondKey, frameBytes)
            if (!info.isV2 || info.service.isBlank() || info.service == "unknown") {
                ""
            } else {
                "${info.service} \u00b7 ${info.user}"
            }
        } catch (t: Throwable) {
            ""
        }
    }
}
